properties.query:
let alertWindow = 15m;
let seqWindow = 5m;
let classifiedTypes = dynamic(["EO_IR", "SAR", "TargetCoord"]);
let minCopies = 3;
let CopyEvents =
    UAVExfilFlow_CL
    | where TimeGenerated > ago(alertWindow)
    | where AssetType in (classifiedTypes) and ActionType == "copy"
    | project CopyTime = TimeGenerated, SourceAsset, AssetType, Operator, BytesTransferred, TimeBin = bin(TimeGenerated, seqWindow);
let StageEvents =
    UAVExfilFlow_CL
    | where TimeGenerated > ago(alertWindow)
    | where AssetType in (classifiedTypes) and ActionType == "stage"
    | project StageTime = TimeGenerated, SourceAsset, AssetType, DestinationHost, Channel, TimeBin = bin(TimeGenerated, seqWindow);
CopyEvents
| join kind=inner (StageEvents) on SourceAsset, AssetType, TimeBin
| where StageTime >= CopyTime
| summarize CopyCount = count(), FirstCopy = min(CopyTime), LastStage = max(StageTime), TotalBytes = sum(BytesTransferred)
    by SourceAsset, AssetType, Operator, DestinationHost, Channel
| where CopyCount >= minCopies
| extend TriggerReason = strcat("작전정보탈취_대량복사후스테이징_", AssetType, "_", SourceAsset)
| extend Severity = "High"
| project FirstCopy, LastStage, SourceAsset, AssetType, Operator, DestinationHost, Channel, CopyCount, TotalBytes, TriggerReason, Severity
| order by LastStage desc
